var THEMES = {"2": {"e": "🛏️🧸✨", "t": "Nos soirées dans ta chambre"}, "3": {"e": "♟️🃏🥇", "t": "Première fois chez Naia"}, "4": {"e": "💃🕺😂", "t": "Fous rires dans le hall"}, "5": {"e": "🎲👪😊", "t": "Les jeux avec les parents"}, "6": {"e": "😌🧘", "t": "Un moment de repos ensemble"}, "7": {"e": "⚽🥅🤸", "t": "Le foot bulle entre amis"}, "8": {"e": "🌹💗💌", "t": "La surprise de la Saint-Valentin"}, "9": {"e": "🍽️🍝🥂", "t": "Notre resto tous les deux"}, "10": {"e": "🤵🌹💘", "t": "Le costume et la rose"}, "11": {"e": "🇵🇱✈️🕯️", "t": "Notre voyage en Pologne"}, "12": {"e": "🎉🪩🎂", "t": "La soirée d’anniversaire"}, "13": {"e": "🏖️🌊☀️", "t": "Nos vacances en Corse"}, "14": {"e": "🎾🏟️🏆", "t": "Roland-Garros ensemble"}, "15": {"e": "📚✏️📖", "t": "Les révisions du bac"}, "16": {"e": "🏰✨🎠", "t": "Notre journée à Disney"}, "17": {"e": "🇮🇱☀️🫒", "t": "Le voyage en Israël"}, "18": {"e": "🏖️🚤🌅", "t": "Encore la plage et le jet"}, "19": {"e": "🎊🍹🎶", "t": "La grande fête"}, "20": {"e": "🧺🍉🌳", "t": "Notre pique-nique"}, "21": {"e": "🍝🌊👪", "t": "Un déjeuner en famille"}, "23": {"e": "👹💀", "t": "L’école"}, "22": {"e": "🧸🍫 · 🪖", "t": "Nounours / Fauda"}, "24": {"e": "🧑🏻💍👱🏻‍♀️", "t": "Mariage de Yoann et Nao"}};
var TOTAL_PAGES = 25;
var EXCLUDED = [];

var rainTimer = null;
function emojiRain(n) {
  if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  var th = THEMES[n];
  var str = th ? th.e : (n === 1 ? "\uD83E\uDD76\uD83D\uDE1C" : "\u2728");
  var parts;
  if (window.Intl && Intl.Segmenter) {
    parts = Array.from(new Intl.Segmenter(undefined, { granularity: "grapheme" }).segment(str), function(s){ return s.segment; });
  } else {
    parts = Array.from(str);
  }
  var list = parts;
  try {
    var re = new RegExp("[\\p{Extended_Pictographic}\\p{Regional_Indicator}]", "u");
    list = parts.filter(function(p){ return re.test(p); });
  } catch (e) {
    list = parts.filter(function(p){ return p.trim() !== "" && p !== "\u00b7"; });
  }
  if (!list.length) list = ["\u2728"];
  var layer = document.getElementById("rain");
  if (!layer) {
    layer = document.createElement("div");
    layer.id = "rain";
    document.body.appendChild(layer);
  }
  layer.innerHTML = "";
  clearTimeout(rainTimer);
  for (var i = 0; i < 30; i++) {
    var el = document.createElement("span");
    el.className = "rain-e";
    el.textContent = list[i % list.length];
    el.style.left = (Math.random() * 92 + 2) + "vw";
    el.style.fontSize = (1.5 + Math.random() * 1.4) + "rem";
    el.style.animationDuration = (2.4 + Math.random() * 0.4) + "s";
    el.style.animationDelay = (Math.random() * 2.2) + "s";
    el.style.setProperty("--sway", (Math.random() * 16 - 8) + "vw");
    el.style.setProperty("--rot", (Math.random() * 120 - 60) + "deg");
    layer.appendChild(el);
  }
  rainTimer = setTimeout(function(){ layer.innerHTML = ""; }, 5400);
}

function initSite() {
  var pagebar = document.getElementById("pagebar");
  var pagesRoot = document.getElementById("pages");
  var heroCount = document.getElementById("hero-count");

  var availablePages = Object.keys(MANIFEST).map(Number).sort(function(a,b){ return a-b; });
  heroCount.textContent = availablePages.length;

  for (var n = 1; n <= TOTAL_PAGES; n++) {
    if (EXCLUDED.indexOf(n) !== -1) continue;

    var btn = document.createElement("button");
    btn.className = "page-btn";
    btn.textContent = n;
    btn.setAttribute("data-page", n);
    btn.addEventListener("click", (function(num){ return function(){ goToPage(num, true); }; })(n));
    pagebar.appendChild(btn);

    var section = document.createElement("section");
    section.className = "page-section";
    section.id = "page-" + n;

    var head = document.createElement("div");
    head.className = "page-head";
    head.innerHTML = "<span class=\"num\">" + n + "</span><span class=\"of\">page " + n + " / " + TOTAL_PAGES + "</span>";
    section.appendChild(head);
    if (n === 3 || n === 6) {
      var title = document.createElement("h2");
      title.className = "page-memory-title";
      title.textContent = THEMES[n].t + " " + THEMES[n].e;
      section.appendChild(title);
    }

    var items = MANIFEST[n];

    if (n === 1 && !items) {
      var empty = document.createElement("div");
      empty.className = "empty-page";
      empty.innerHTML = "<div class=\"glyph\">🥶😜</div><p>Désolé, on n’a pas pris de photo... on avait trop froid !</p>";
      section.appendChild(empty);
    } else if (items && items.length) {
      var gallery = document.createElement("div");
      gallery.className = "gallery";
      for (var i = 0; i < items.length; i++) {
        var item = items[i];
        var tile = document.createElement("div");
        tile.className = "tile" + (item.type === "video" ? " video" : "");
        var th = THEMES[n] || { e: "\u2728", t: "Un moment \u00e0 nous" };
        var media = document.createElement(item.type === "image" ? "img" : "video");
        if (item.type === "image") {
          media.loading = "lazy";
          media.alt = th.t;
          media.src = item.file;
        } else {
          media.preload = "metadata";
          media.muted = true;
          media.playsInline = true;
          media.src = item.file + "#t=0.5";
        }
        tile.appendChild(media);
        var ph = document.createElement("div");
        ph.className = "tile-ph";
        var emoji = document.createElement("div");
        emoji.className = "ph-emoji";
        emoji.textContent = th.e;
        var label = document.createElement("div");
        label.className = "ph-text";
        label.textContent = th.t;
        ph.appendChild(emoji);
        ph.appendChild(label);
        tile.appendChild(ph);
        (function(phEl, mediaEl){
          function reveal(){ phEl.classList.add("hide"); }
          if (mediaEl.tagName === "IMG") {
            if (mediaEl.complete && mediaEl.naturalWidth > 0) { reveal(); }
            else { mediaEl.addEventListener("load", reveal); }
          } else {
            mediaEl.addEventListener("loadeddata", reveal);
            if (mediaEl.readyState >= 2) { reveal(); }
          }
        })(ph, media);
        tile.addEventListener("click", (function(it){ return function(){ openLightbox(it); }; })(item));
        gallery.appendChild(tile);
      }
      section.appendChild(gallery);
    } else {
      var soon = document.createElement("div");
      soon.className = "soon-page";
      soon.innerHTML = "<p>Cette page arrive bientôt</p>";
      section.appendChild(soon);
    }

    pagesRoot.appendChild(section);
  }

  function goToPage(n, withRain) {
    var btns = document.querySelectorAll(".page-btn");
    for (var i = 0; i < btns.length; i++) {
      btns[i].classList.toggle("active", Number(btns[i].getAttribute("data-page")) === n);
    }
    var secs = document.querySelectorAll(".page-section");
    for (var j = 0; j < secs.length; j++) {
      secs[j].classList.toggle("active", secs[j].id === "page-" + n);
    }
    var activeBtn = document.querySelector(".page-btn[data-page=\"" + n + "\"]");
    if (activeBtn) activeBtn.scrollIntoView({ inline: "center", block: "nearest", behavior: "smooth" });
    history.replaceState(null, "", "#page" + n);
    if (withRain) emojiRain(n);
  }

  var lightbox = document.getElementById("lightbox");
  var lightboxContent = document.getElementById("lightbox-content");

  function openLightbox(item) {
    var media = document.createElement(item.type === "image" ? "img" : "video");
    if (item.type === "image") {
      media.alt = "Photo de l’album";
    } else {
      media.controls = true;
      media.autoplay = true;
      media.playsInline = true;
    }
    media.src = item.file;
    lightboxContent.textContent = "";
    lightboxContent.appendChild(media);
    lightbox.classList.add("open");
  }
  function closeLightbox() {
    lightbox.classList.remove("open");
    lightboxContent.innerHTML = "";
  }
  document.getElementById("lightbox-close").addEventListener("click", closeLightbox);
  lightbox.addEventListener("click", function(e){ if (e.target === lightbox) closeLightbox(); });
  document.addEventListener("keydown", function(e){ if (e.key === "Escape") closeLightbox(); });

  var hashMatch = location.hash.match(/^#page(\d+)$/);
  var startPage = hashMatch ? Number(hashMatch[1]) : 1;
  if (!Number.isInteger(startPage) || startPage < 1 || startPage > TOTAL_PAGES || EXCLUDED.indexOf(startPage) !== -1) startPage = 1;
  goToPage(startPage);
}

initSite();
